    13→#[tokio::main]
    14→async fn main() -> Result<()> {
    15→    // Parse command line arguments first
    16→    // This allows --version and --help to work without any side effects
    17→    let cli = Cli::parse();
    18→
    19→    // Handle key management commands before showing welcome screen
    20→    match &cli.command {
    21→        Some(Commands::Key { command }) => {
    22→            // Initialize minimal logging for key commands
    23→            tracing_subscriber::fmt::init();
    24→            return cli::handle_key_command(command.clone(), cli.config.clone()).await;
    25→        }
    26→        Some(Commands::Run) | None => {
    27→            // Continue with normal daemon operation
    28→        }
    29→    }
    30→
    31→    // Prepare version string for ASCII art
    32→    let version = format!("Omikuji v{}", env!("CARGO_PKG_VERSION"));
    33→    // The ASCII art is 100 chars wide, so center the version string
    34→    let width = 100;
    35→    let version_line = format!("{version:^width$}");
    36→    let welcome = ui::welcome_screen::WELCOME_SCREEN.replace("{version_line}", &version_line);
    37→    println!("{welcome}");
    38→
    39→    // Initialize logging after argument parsing
    40→    tracing_subscriber::fmt::init();
    41→
    42→    // Load .env file if it exists
    43→    match dotenv::dotenv() {
    44→        Ok(path) => info!("Loaded .env file from: {:?}", path),
    45→        Err(e) => info!("No .env file loaded: {}", e),
    46→    }
    47→
    48→    // Determine configuration path
    49→    let config_path = cli.config.unwrap_or_else(config::default_config_path);
    50→    info!("Using configuration file: {:?}", config_path);
    51→
    52→    // Load and validate configuration
    53→    let config = match config::load_config(&config_path) {
    54→        Ok(cfg) => {
    55→            info!("Configuration loaded successfully");
    56→            cfg
    57→        }
    58→        Err(e) => {
    59→            error!("Failed to load configuration: {}", e);
    60→            return Err(anyhow::anyhow!("Configuration error: {}", e));
    61→        }
    62→    };
    63→
    64→    // Initialize metrics configuration
    65→    use crate::metrics::{init_metrics_config, ConfigMetrics};
    66→    init_metrics_config(config.metrics.clone());
    67→
    68→    // Record configuration metrics
    69→    ConfigMetrics::record_startup_info(&config);
    70→
    71→    // Display loaded configuration
    72→    info!(
    73→        "Loaded {} network(s) and {} datafeed(s)",
    74→        config.networks.len(),
    75→        config.datafeeds.len()
    76→    );
    77→
    78→    for network in &config.networks {
    79→        let rpc_url = network
    80→            .nodes
    81→            .first()
    82→            .map(|node| node.rpc_url.as_str())
    83→            .unwrap_or("no nodes configured");
    84→        info!("Network: {} ({})", network.name, rpc_url);
    85→    }
    86→
    87→    for datafeed in &config.datafeeds {
    88→        info!(
    89→            "Datafeed: {} on network {}",
    90→            datafeed.name, datafeed.networks
    91→        );
    92→    }
    93→
    94→    // Initialize network connections
    95→    let mut network_manager = match network::NetworkManager::new(&config.networks).await {
    96→        Ok(manager) => {
    97→            info!("Network connections initialized successfully");
    98→            manager
    99→        }
   100→        Err(e) => {
   101→            error!("Failed to initialize network connections: {}", e);
   102→            return Err(anyhow::anyhow!("Network initialization error: {}", e));
   103→        }
   104→    };
   105→
   106→    // Load wallets based on key storage configuration
   107→    let key_storage = create_key_storage(&config)
   108→        .await
   109→        .context("Failed to initialize key storage")?;
   110→
   111→    for network in &config.networks {
   112→        match network_manager
   113→            .load_wallet_from_key_storage(&network.name, key_storage.as_ref())
   114→            .await
   115→        {
   116→            Ok(_) => {
   117→                info!("Successfully loaded wallet for network {}", network.name);
   118→            }
   119→            Err(e) => {
   120→                // For backward compatibility, try environment variable if keyring fails
   121→                if config.key_storage.storage_type == "keyring" {
   122→                    debug!(
   123→                        "Keyring lookup failed for network {}, trying environment variable",
   124→                        network.name
   125→                    );
   126→
   127→                    match network_manager
   128→                        .load_wallet_from_env(&network.name, &cli.private_key_env)
   129→                        .await
   130→                    {
   131→                        Ok(_) => {
   132→                            info!(
   133→                                "Successfully loaded wallet for network {} from environment variable",
   134→                                network.name
   135→                            );
   136→                            continue;
   137→                        }
   138→                        Err(env_err) => {
   139→                            debug!("Failed to load from env var: {:?}", env_err);
   140→                        }
   141→                    }
   142→                }
   143→
   144→                error!("Failed to load wallet for network {}: {}", network.name, e);
   145→                warn!(
   146→                    "Transactions on {} network will not be possible",
   147→                    network.name
   148→                );
   149→            }
   150→        }
   151→    }
   152→
   153→    // Now wrap in Arc for sharing across threads
   154→    let network_manager = Arc::new(network_manager);
   155→
   156→    // Initialize database connection (optional - continues if not available)
   157→    info!("Checking for database configuration...");
   158→    let database_pool = match std::env::var("DATABASE_URL") {
   159→        Ok(_) => {
   160→            debug!("DATABASE_URL environment variable found, attempting database connection");
   161→            match database::establish_connection().await {
   162→                Ok(pool) => {
   163→                    info!("Database connection established successfully");
   164→
   165→                    // Check if we should skip migrations
   166→                    let skip_migrations = std::env::var("SKIP_MIGRATIONS")
   167→                        .unwrap_or_else(|_| "false".to_string())
   168→                        .to_lowercase()
   169→                        == "true";
   170→
   171→                    if skip_migrations {
   172→                        info!("SKIP_MIGRATIONS is set, skipping database migrations");
   173→
   174→                        // Verify tables exist and are accessible
   175→                        match database::connection::verify_tables(&pool).await {
   176→                            Ok(_) => {
   177→                                info!("Database tables verified successfully");
   178→                                info!("Database initialized with feed logging and transaction tracking enabled");
   179→                                ConfigMetrics::set_database_status(true);
   180→                                Some(pool)
   181→                            }
   182→                            Err(e) => {
   183→                                error!("Database tables are not accessible: {}", e);
   184→                                error!("Please ensure the required tables exist (feed_log, transaction_log, gas_token_prices)");
   185→                                error!("Continuing without database support");
   186→                                ConfigMetrics::set_database_status(false);
   187→                                None
   188→                            }
   189→                        }
   190→                    } else {
   191→                        // Run migrations as normal
   192→                        if let Err(e) = database::connection::run_migrations(&pool).await {
   193→                            error!("Failed to run database migrations: {}", e);
   194→                            error!("You can skip migrations by setting SKIP_MIGRATIONS=true");
   195→                            error!("Continuing without database support");
   196→                            ConfigMetrics::set_database_status(false);
   197→                            None
   198→                        } else {
   199→                            info!("Database migrations completed successfully");
   200→                            info!("Database initialized with feed logging and transaction tracking enabled");
   201→                            ConfigMetrics::set_database_status(true);
   202→                            Some(pool)
   203→                        }
   204→                    }
   205→                }
   206→                Err(e) => {
   207→                    error!("Failed to establish database connection: {}", e);
   208→                    error!("Continuing without database logging");
   209→                    ConfigMetrics::set_database_status(false);
   210→                    None
   211→                }
   212→            }
   213→        }
   214→        Err(_) => {
   215→            info!("DATABASE_URL not set - running without database logging");
   216→            info!("To enable database logging, set DATABASE_URL environment variable");
   217→            ConfigMetrics::set_database_status(false);
   218→            None
   219→        }
   220→    };
   221→
   222→    // Initialize cleanup manager if database is available
   223→    let cleanup_manager = if let Some(ref pool) = database_pool {
   224→        let repository = Arc::new(database::FeedLogRepository::new(pool.clone()));
   225→        let mut cleanup_manager =
   226→            database::cleanup::CleanupManager::new(config.clone(), repository).await?;
   227→
   228→        // Start cleanup scheduler
   229→        if let Err(e) = cleanup_manager.start().await {
   230→            error!("Failed to start cleanup scheduler: {}", e);
   231→        }
   232→
   233→        Some(cleanup_manager)
   234→    } else {
   235→        None
   236→    };
   237→
   238→    // Initialize gas price manager
   239→    let gas_price_manager = if config.gas_price_feeds.enabled {
   240→        info!("Initializing gas price feed manager");
   241→
   242→        // Build token mappings from network configurations
   243→        let mut token_mappings = std::collections::HashMap::new();
   244→        for network in &config.networks {
   245→            token_mappings.insert(network.name.clone(), network.gas_token.clone());
   246→        }
   247→
   248→        // Create transaction repository if database is available
   249→        let tx_repo = database_pool.as_ref().map(|pool| {
   250→            Arc::new(database::transaction_repository::TransactionLogRepository::new(pool.clone()))
   251→        });
   252→
   253→        let gas_price_manager = Arc::new(gas_price::GasPriceManager::new(
   254→            config.gas_price_feeds.clone(),
   255→            token_mappings,
   256→            tx_repo,
   257→        ));
   258→
   259→        // Start the price update loop
   260→        gas_price_manager.clone().start().await;
   261→
   262→        Some(gas_price_manager)
   263→    } else {
   264→        info!("Gas price feeds are disabled");
   265→        None
   266→    };
   267→
   268→    // Initialize and start datafeed monitoring
   269→    let mut feed_manager = if let Some(ref pool) = &database_pool {
   270→        let mut manager = datafeed::FeedManager::new(config.clone(), Arc::clone(&network_manager))
   271→            .with_repository(pool.clone());
   272→
   273→        // Add gas price manager if available
   274→        if let Some(ref gas_price_manager) = gas_price_manager {
   275→            manager = manager.with_gas_price_manager(Arc::clone(gas_price_manager));
   276→        }
   277→
   278→        manager
   279→    } else {
   280→        let mut manager = datafeed::FeedManager::new(config.clone(), Arc::clone(&network_manager));
   281→
   282→        // Add gas price manager if available
   283→        if let Some(ref gas_price_manager) = gas_price_manager {
   284→            manager = manager.with_gas_price_manager(Arc::clone(gas_price_manager));
   285→        }
   286→
   287→        manager
   288→    };
   289→
   290→    feed_manager.start().await;
   291→
   292→    // Initialize and start scheduled task manager
   293→    let scheduled_task_manager = if !config.scheduled_tasks.is_empty() {
   294→        info!(
   295→            "Initializing scheduled task manager with {} tasks",
   296→            config.scheduled_tasks.len()
   297→        );
   298→
   299→        // Debug output for each scheduled task
   300→        for (i, task) in config.scheduled_tasks.iter().enumerate() {
   301→            debug!("Scheduled task {}: {:?}", i, task);
   302→            info!(
   303→                "Task '{}': schedule='{}', network='{}', function='{}'",
   304→                task.name, task.schedule, task.network, task.target_function.function
   305→            );
   306→            if let Some(ref condition) = task.check_condition {
   307→                match condition {
   308→                    scheduled_tasks::models::CheckCondition::Property {
   309→                        property,
   310→                        expected_value,
   311→                        ..
   312→                    } => {
   313→                        debug!(
   314→                            "  Condition: property '{}' should be {:?}",
   315→                            property, expected_value
   316→                        );
   317→                    }
   318→                    scheduled_tasks::models::CheckCondition::Function {
   319→                        function,
   320→                        expected_value,
   321→                        ..
   322→                    } => {
   323→                        debug!(
   324→                            "  Condition: function '{}' should return {:?}",
   325→                            function, expected_value
   326→                        );
   327→                    }
   328→                }
   329→            }
   330→        }
   331→
   332→        let mut task_manager = scheduled_tasks::ScheduledTaskManager::new(
   333→            config.scheduled_tasks.clone(),
   334→            Arc::clone(&network_manager),
   335→        )
   336→        .await
   337→        .context("Failed to create scheduled task manager")?;
   338→
   339→        // Add gas price manager if available
   340→        if let Some(ref gas_price_manager) = gas_price_manager {
   341→            task_manager = task_manager.with_gas_price_manager(Arc::clone(gas_price_manager));
   342→        }
   343→
   344→        // Add transaction repository if database is available
   345→        if let Some(ref pool) = &database_pool {
   346→            let tx_repo = Arc::new(
   347→                database::transaction_repository::TransactionLogRepository::new(pool.clone()),
   348→            );
   349→            task_manager = task_manager.with_tx_log_repo(tx_repo);
   350→        }
   351→
   352→        task_manager
   353→            .start()
   354→            .await
   355→            .context("Failed to start scheduled task manager")?;
   356→
   357→        Some(Arc::new(task_manager))
   358→    } else {
   359→        info!("No scheduled tasks configured");
   360→        None
   361→    };
   362→
   363→    // Start Prometheus metrics server
   364→    if let Err(e) = metrics::start_metrics_server(config.metrics.port).await {
   365→        error!("Failed to start metrics server: {}", e);
   366→        error!("Continuing without metrics endpoint");
   367→    } else {
   368→        info!(
   369→            "Prometheus metrics available at http://0.0.0.0:{}/metrics",
   370→            config.metrics.port
   371→        );
   372→
   373→        // Update metrics server status
   374→        ConfigMetrics::set_metrics_server_status(true, config.metrics.port);
   375→    }
   376→
   377→    // Initialize and start event monitoring
   378→    let event_monitor_handles = if !config.event_monitors.is_empty() {
   379→        info!(
   380→            "Initializing event monitoring with {} monitors",
   381→            config.event_monitors.len()
   382→        );
   383→
   384→        // Debug output for each event monitor
   385→        for monitor in &config.event_monitors {
   386→            info!(
   387→                "Event monitor '{}': network='{}', contract='{}', event='{}'",
   388→                monitor.name, monitor.network, monitor.contract_address, monitor.event_signature
   389→            );
   390→            debug!(
   391→                "  Webhook: {:?} {}",
   392→                monitor.webhook.method, monitor.webhook.url
   393→            );
   394→        }
   395→
   396→        // Create event monitoring components
   397→        let webhook_caller = Arc::new(omikuji::event_monitors::WebhookCaller::new());
   398→        let response_handler = Arc::new(omikuji::event_monitors::ResponseHandler::new(
   399→            Arc::clone(&network_manager),
   400→            Arc::new(config.clone()),
   401→        ));
   402→
   403→        // Create event listener with all configured monitors
   404→        let event_listener = if let Some(ref pool) = &database_pool {
   405→            omikuji::event_monitors::EventListener::with_database(
   406→                Arc::clone(&network_manager),
   407→                webhook_caller,
   408→                response_handler,
   409→                config.event_monitors.clone(),
   410→                pool.clone(),
   411→            )
   412→        } else {
   413→            omikuji::event_monitors::EventListener::new(
   414→                Arc::clone(&network_manager),
   415→                webhook_caller,
   416→                response_handler,
   417→                config.event_monitors.clone(),
   418→            )
   419→        };
   420→
   421→        // Start monitoring
   422→        match event_listener.start_monitoring().await {
   423→            Ok(handles) => {
   424→                info!(
   425→                    "Started event monitoring with {} active subscriptions",
   426→                    handles.len()
   427→                );
   428→                Some(handles)
   429→            }
   430→            Err(e) => {
   431→                error!("Failed to start event monitoring: {}", e);
   432→                None
   433→            }
   434→        }
   435→    } else {
   436→        info!("No event monitors configured");
   437→        None
   438→    };
   439→
   440→    // Start wallet balance monitor
   441→    let mut wallet_monitor =
   442→        omikuji::wallet::WalletBalanceMonitor::new(Arc::clone(&network_manager));
   443→    if let Some(ref gas_price_manager) = gas_price_manager {
   444→        wallet_monitor = wallet_monitor.with_gas_price_manager(Arc::clone(gas_price_manager));
   445→    }
   446→    tokio::spawn(async move {
   447→        wallet_monitor.start().await;
   448→    });
   449→
   450→    info!("Omikuji starting up...");
   451→
   452→    // Get chain ID and block number for each network as a test
   453→    for network in &config.networks {
   454→        match network_manager.get_chain_id(&network.name).await {
   455→            Ok(chain_id) => info!("Network {} chain ID: {}", network.name, chain_id),
   456→            Err(e) => error!("Failed to get chain ID for network {}: {}", network.name, e),
   457→        }
   458→
   459→        match network_manager.get_block_number(&network.name).await {
   460→            Ok(block_number) => info!("Network {} current block: {}", network.name, block_number),
   461→            Err(e) => error!(
   462→                "Failed to get block number for network {}: {}",
   463→                network.name, e
   464→            ),
   465→        }
   466→    }
   467→
   468→    // Keep the application running
   469→    tokio::signal::ctrl_c().await?;
   470→    info!("Received shutdown signal, stopping...");
   471→
   472→    // Stop scheduled task manager if running
   473→    if let Some(task_manager) = scheduled_task_manager {
   474→        if let Err(e) = task_manager.stop().await {
   475→            error!("Error stopping scheduled task manager: {}", e);
   476→        } else {
   477→            info!("Scheduled task manager stopped successfully");
   478→        }
   479→    }
   480→
   481→    // Stop event monitors if running
   482→    if let Some(handles) = event_monitor_handles {
   483→        info!("Stopping event monitors...");
   484→        for handle in handles {
   485→            handle.abort();
   486→        }
   487→        info!("Event monitors stopped successfully");
   488→    }
   489→
   490→    // Stop cleanup manager if running
   491→    if let Some(mut cleanup_manager) = cleanup_manager {
   492→        if let Err(e) = cleanup_manager.stop().await {
   493→            error!("Error stopping cleanup manager: {}", e);
   494→        }
   495→    }
   496→
   497→    Ok(())
   498→}
