   602→    #[test]
   603→    fn test_version_string_formatting() {
   604→        let version = format!("Omikuji v{}", env!("CARGO_PKG_VERSION"));
   605→        let width = 100;
   606→        let version_line = format!("{version:^width$}");
   607→
   608→        // Check that version line is centered and has correct width
   609→        assert_eq!(version_line.len(), 100);
   610→        assert!(version_line.contains(&version));
   611→
   612→        // Check that padding is roughly equal on both sides
