    10→/// Errors that can occur when fetching data
    11→#[derive(Debug, Error)]
    12→pub enum FetchError {
    13→    #[error("HTTP error with status code: {0}")]
    14→    Http(u16),
    15→
    16→    #[error("Network error: {0}")]
    17→    Network(String),
    18→
    19→    #[error("JSON parsing error: {0}")]
    20→    Json(String),
    21→}
    22→
    23→/// Fetches JSON data from a given URL
    24→pub struct Fetcher {
    25→    client: Client,
    26→}
    27→
    28→impl Fetcher {
    29→    /// Creates a new Fetcher with a reusable HTTP client
    30→    pub fn new() -> Self {
    31→        let client = Client::builder()
    32→            .timeout(std::time::Duration::from_secs(30))
    33→            .build()
    34→            .expect("Failed to create HTTP client");
    35→
    36→        Self { client }
    37→    }
    38→
    39→    /// Fetches JSON data from the specified URL
    40→    /// Returns the parsed JSON value on success
    41→    pub async fn fetch_json(&self, url: &str, feed_name: &str, network: &str) -> Result<Value> {
    42→        debug!(
    43→            "Fetching data from: {} for feed {}/{}",
    44→            url, feed_name, network
    45→        );
    46→
    47→        let start_time = Instant::now();
    48→
    49→        let response = match self
    50→            .client
    51→            .get(url)
    52→            .header("Accept", "application/json")
    53→            .send()
    54→            .await
    55→        {
    56→            Ok(resp) => resp,
    57→            Err(e) => {
    58→                let duration = start_time.elapsed();
    59→                error!("Network error fetching from {}: {}", url, e);
    60→
    61→                // Record HTTP error metric
    62→                DatasourceMetrics::record_http_error(
    63→                    feed_name,
