   217→        Ok(decoded._0)
   218→    }
   219→
   220→    /// Submit a new price to the FluxAggregator contract with gas estimation and retry logic
   221→    pub async fn submit_price_with_gas_estimation(
   222→        &self,
   223→        round_id: U256,
   224→        price: I256,
   225→        network_config: &NetworkConfig,
   226→        feed_name: &str,
   227→        tx_log_repo: Option<Arc<TransactionLogRepository>>,
   228→        from_address: Option<Address>,
   229→    ) -> Result<TransactionReceipt> {
   230→        let gas_config = &network_config.gas_config;
   231→        let fee_bumping = &gas_config.fee_bumping;
   232→
   233→        // Create the function call
   234→        let call = IFluxAggregator::submitCall {
   235→            _roundId: round_id,
   236→            _submission: price,
   237→        };
   238→
   239→        // Build base transaction request
   240→        let mut tx = TransactionRequest::default()
   241→            .to(self.address)
   242→            .input(call.abi_encode().into());
   243→
   244→        // Set from address if provided (needed for accurate gas estimation)
   245→        if let Some(from) = from_address {
   246→            tx = tx.from(from);
   247→        }
   248→
   249→        // Estimate gas
   250→        let gas_estimator = crate::gas::GasEstimator::<T, P>::new(
   251→            Arc::new(self.provider.clone()),
   252→            network_config.clone(),
   253→        );
   254→        let mut gas_estimate = gas_estimator.estimate_gas(&tx).await?;
   255→
   256→        let mut attempt = 0;
   257→        let max_attempts = if fee_bumping.enabled {
   258→            fee_bumping.max_retries + 1
   259→        } else {
   260→            1
   261→        };
   262→
   263→        loop {
   264→            attempt += 1;
   265→
   266→            // Apply gas settings
   267→            tx = tx.with_gas_limit(gas_estimate.gas_limit.to::<u64>());
   268→
   269→            // Apply fee settings based on transaction type
   270→            match network_config.transaction_type.to_lowercase().as_str() {
   271→                "legacy" => {
   272→                    if let Some(gas_price) = gas_estimate.gas_price {
   273→                        tx = tx.with_gas_price(gas_price.to::<u128>());
   274→                    }
   275→                }
   276→                "eip1559" => {
   277→                    if let Some(max_fee) = gas_estimate.max_fee_per_gas {
   278→                        tx = tx.with_max_fee_per_gas(max_fee.to::<u128>());
   279→                    }
   280→                    if let Some(priority_fee) = gas_estimate.max_priority_fee_per_gas {
   281→                        tx = tx.with_max_priority_fee_per_gas(priority_fee.to::<u128>());
   282→                    }
   283→                }
   284→                _ => {
   285→                    warn!("Unknown transaction type, defaulting to EIP-1559");
   286→                    if let Some(max_fee) = gas_estimate.max_fee_per_gas {
   287→                        tx = tx.with_max_fee_per_gas(max_fee.to::<u128>());
   288→                    }
   289→                    if let Some(priority_fee) = gas_estimate.max_priority_fee_per_gas {
   290→                        tx = tx.with_max_priority_fee_per_gas(priority_fee.to::<u128>());
   291→                    }
   292→                }
   293→            }
   294→
   295→            info!("Sending transaction (attempt {})", attempt);
   296→
   297→            // Record contract write attempt
   298→            let write_start = Instant::now();
   299→
   300→            // Send transaction
   301→            let pending_tx = match self.provider.send_transaction(tx.clone()).await {
   302→                Ok(tx) => tx,
   303→                Err(e) => {
   304→                    let write_duration = write_start.elapsed();
   305→                    error!("Failed to send transaction: {}", e);
   306→
   307→                    // Record failed contract write
   308→                    ContractMetrics::record_contract_write(
   309→                        feed_name,
   310→                        &network_config.name,
   311→                        false,
   312→                        write_duration,
   313→                        None,
   314→                    );
   315→
   316→                    // Check for specific error types
   317→                    let error_str = e.to_string();
   318→                    if error_str.contains("revert") {
   319→                        ContractMetrics::record_transaction_revert(
   320→                            feed_name,
   321→                            &network_config.name,
   322→                            &error_str,
   323→                        );
   324→                    }
   325→
   326→                    if attempt >= max_attempts {
   327→                        ContractMetrics::record_transaction_retry(
   328→                            feed_name,
   329→                            &network_config.name,
   330→                            "max_attempts_reached",
   331→                            attempt as u32,
   332→                        );
   333→                        return Err(anyhow::anyhow!(
   334→                            "Failed to send transaction after {} attempts: {}",
   335→                            attempt as u32,
   336→                            e
   337→                        ));
   338→                    }
   339→
   340→                    ContractMetrics::record_transaction_retry(
   341→                        feed_name,
   342→                        &network_config.name,
   343→                        "send_error",
   344→                        attempt as u32,
   345→                    );
   346→                    continue;
   347→                }
   348→            };
   349→
   350→            let tx_hash = *pending_tx.tx_hash();
   351→            info!("Transaction sent: 0x{:x}", tx_hash);
   352→
   353→            // Wait for confirmation with timeout
   354→            let wait_duration = Duration::from_secs(fee_bumping.initial_wait_seconds);
   355→
   356→            // Record transaction submission time
   357→            let submission_time = std::time::SystemTime::now()
   358→                .duration_since(std::time::UNIX_EPOCH)
   359→                .unwrap()
   360→                .as_secs();
   361→
   362→            match tokio::time::timeout(
   363→                wait_duration,
   364→                pending_tx.with_required_confirmations(1).get_receipt(),
   365→            )
   366→            .await
   367→            {
   368→                Ok(Ok(receipt)) => {
   369→                    let write_duration = write_start.elapsed();
   370→                    info!("Transaction confirmed: 0x{:x}", tx_hash);
   371→
   372→                    // Record successful contract write
   373→                    ContractMetrics::record_contract_write(
   374→                        feed_name,
   375→                        &network_config.name,
   376→                        true,
   377→                        write_duration,
   378→                        Some(&format!("0x{tx_hash:x}")),
   379→                    );
   380→
   381→                    // Record confirmation time
   382→                    let confirmation_time = std::time::SystemTime::now()
   383→                        .duration_since(std::time::UNIX_EPOCH)
   384→                        .unwrap()
   385→                        .as_secs();
   386→                    ContractMetrics::record_confirmation_time(
   387→                        feed_name,
   388→                        &network_config.name,
   389→                        submission_time,
   390→                        confirmation_time,
   391→                    );
   392→
   393→                    // Record gas metrics
   394→                    GasMetrics::record_transaction(
   395→                        feed_name,
   396→                        &network_config.name,
   397→                        &receipt,
   398→                        gas_estimate.gas_limit,
   399→                        &network_config.transaction_type,
   400→                    );
   401→
   402→                    // Log transaction if repository is available
   403→                    if let Some(repo) = &tx_log_repo {
   404→                        if let Err(e) = Self::log_transaction(
   405→                            repo,
   406→                            &tx_hash,
   407→                            &receipt,
   408→                            feed_name,
   409→                            &network_config.name,
   410→                            &gas_estimate,
   411→                            &network_config.transaction_type,
   412→                        )
   413→                        .await
   414→                        {
   415→                            error!("Failed to log transaction: {}", e);
   416→                        }
   417→                    }
   418→
   419→                    return Ok(receipt);
   420→                }
   421→                Ok(Err(e)) => {
   422→                    error!("Transaction failed: {}", e);
   423→
   424→                    // Record failed transaction
   425→                    GasMetrics::record_failed_transaction(
   426→                        feed_name,
   427→                        &network_config.name,
   428→                        gas_estimate.gas_limit,
   429→                        gas_estimate.gas_price.or(gas_estimate.max_fee_per_gas),
   430→                        &network_config.transaction_type,
   431→                        &e.to_string(),
   432→                    );
   433→
   434→                    if attempt >= max_attempts {
   435→                        return Err(anyhow::anyhow!(
   436→                            "Transaction failed after {} attempts: {}",
   437→                            attempt as u32,
   438→                            e
   439→                        ));
   440→                    }
   441→                }
   442→                Err(_) => {
   443→                    warn!(
   444→                        "Transaction timed out after {} seconds: 0x{:x}",
   445→                        wait_duration.as_secs(),
   446→                        tx_hash
   447→                    );
   448→                    if attempt >= max_attempts {
   449→                        return Err(anyhow::anyhow!(
   450→                            "Transaction timed out after {} attempts",
   451→                            attempt
   452→                        ));
   453→                    }
   454→                }
   455→            }
   456→
   457→            // Bump fees for retry
   458→            if fee_bumping.enabled && attempt < max_attempts {
   459→                gas_estimate = gas_estimator.bump_fees(&gas_estimate, attempt);
   460→                info!("Bumping fees for retry attempt {}", attempt + 1);
   461→            }
   462→        }
   463→    }
