   465→    /// Log transaction details to the database
   466→    async fn log_transaction(
   467→        repo: &Arc<TransactionLogRepository>,
   468→        tx_hash: &alloy::primitives::TxHash,
   469→        receipt: &TransactionReceipt,
   470→        feed_name: &str,
   471→        network_name: &str,
   472→        gas_estimate: &GasEstimate,
   473→        tx_type: &str,
   474→    ) -> Result<()> {
   475→        let gas_used = receipt.gas_used;
   476→        let gas_limit = gas_estimate.gas_limit;
   477→        let efficiency_percent = (gas_used as f64 / gas_limit.to::<u128>() as f64) * 100.0;
   478→
   479→        let gas_price_gwei = if let Some(price) = gas_estimate.gas_price {
   480→            alloy::primitives::utils::format_units(price, "gwei")?.parse::<f64>()?
   481→        } else if let Some(max_fee) = gas_estimate.max_fee_per_gas {
   482→            alloy::primitives::utils::format_units(max_fee, "gwei")?.parse::<f64>()?
   483→        } else {
   484→            0.0
   485→        };
   486→
   487→        let total_cost_wei = U256::from(gas_used) * gas_estimate.gas_price.unwrap_or(U256::ZERO);
   488→
   489→        let details = TransactionDetails {
   490→            tx_hash: format!("0x{tx_hash:x}"),
   491→            feed_name: feed_name.to_string(),
   492→            network: network_name.to_string(),
   493→            gas_limit: gas_limit.to::<u64>(),
   494→            gas_used: gas_used as u64,
   495→            gas_price_gwei,
   496→            total_cost_wei: total_cost_wei.to::<u128>(),
   497→            efficiency_percent,
   498→            tx_type: tx_type.to_string(),
   499→            status: if receipt.status() {
   500→                "success"
   501→            } else {
   502→                "failed"
   503→            }
   504→            .to_string(),
   505→            block_number: receipt.block_number.unwrap_or(0),
   506→            error_message: None,
   507→        };
   508→
   509→        repo.save_transaction(details).await?;
   510→        Ok(())
   511→    }
   512→}
