use crate::config::models::Network as NetworkConfig;
use crate::database::TransactionLogRepository;
use crate::gas::GasEstimate;
use crate::metrics::gas_metrics::{GasMetrics, TransactionDetails};
use crate::metrics::ContractMetrics;
use alloy::{
    network::{Ethereum, TransactionBuilder},
    primitives::{Address, I256, U256},
    providers::Provider,
    rpc::types::{BlockId, TransactionReceipt, TransactionRequest},
    sol,
    sol_types::SolCall,
    transports::Transport,
};
use anyhow::Result;
use std::sync::Arc;
use std::time::Instant;
use tokio::time::Duration;
use tracing::{error, info, warn};

// Define the Solidity interface using alloy's sol! macro
sol! {
    #[sol(rpc)]
    interface IFluxAggregator {
        function latestAnswer() external view returns (int256);
        function latestTimestamp() external view returns (uint256);
        function latestRound() external view returns (uint256);
        function getAnswer(uint256 _roundId) external view returns (int256);
        function getTimestamp(uint256 _roundId) external view returns (uint256);
        function decimals() external view returns (uint8);
        function description() external view returns (string memory);
        function version() external view returns (uint256);
        function minSubmissionValue() external view returns (int256);
        function maxSubmissionValue() external view returns (int256);
        function getRoundData(uint80 _roundId) external view returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
        function latestRoundData() external view returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
        function submit(uint256 _roundId, int256 _submission) external;
        function oracleRoundState(address _oracle, uint32 _queriedRoundId) external view returns (bool _eligibleToSubmit, uint32 _roundId, int256 _latestSubmission, uint64 _startedAt, uint64 _timeout, uint128 _availableFunds, uint8 _oracleCount, uint128 _paymentAmount);
    }
}

/// Wrapper for FluxAggregator contract interactions
pub struct FluxAggregatorContract<T: Transport + Clone, P: Provider<T, Ethereum>> {
    address: Address,
    provider: P,
    _phantom: std::marker::PhantomData<T>,
}

impl<T: Transport + Clone, P: Provider<T, Ethereum> + Clone> FluxAggregatorContract<T, P> {
    /// Create a new FluxAggregator contract instance
    pub fn new(address: Address, provider: P) -> Self {
        Self {
            address,
            provider,
            _phantom: std::marker::PhantomData,
        }
    }

    /// Get the latest answer from the contract
    pub async fn latest_answer(&self) -> Result<I256> {
        self.latest_answer_with_metrics(None, None).await
    }

    /// Get the latest answer from the contract with metrics
    pub async fn latest_answer_with_metrics(
        &self,
        feed_name: Option<&str>,
        network: Option<&str>,
    ) -> Result<I256> {
        let start = Instant::now();
        let call = IFluxAggregator::latestAnswerCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());

        match self.provider.call(&tx).block(BlockId::latest()).await {
            Ok(result) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestAnswer",
                        true,
                        duration,
                        None,
                    );
                }

                let decoded = IFluxAggregator::latestAnswerCall::abi_decode_returns(&result, true)?;
                Ok(decoded._0)
            }
            Err(e) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestAnswer",
                        false,
                        duration,
                        Some(&e.to_string()),
                    );
                }

                Err(e.into())
            }
        }
    }

    /// Get the latest timestamp
    pub async fn latest_timestamp(&self) -> Result<U256> {
        self.latest_timestamp_with_metrics(None, None).await
    }

    /// Get the latest timestamp with metrics
    pub async fn latest_timestamp_with_metrics(
        &self,
        feed_name: Option<&str>,
        network: Option<&str>,
    ) -> Result<U256> {
        let start = Instant::now();
        let call = IFluxAggregator::latestTimestampCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());

        match self.provider.call(&tx).block(BlockId::latest()).await {
            Ok(result) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestTimestamp",
                        true,
                        duration,
                        None,
                    );
                }

                let decoded =
                    IFluxAggregator::latestTimestampCall::abi_decode_returns(&result, true)?;
                Ok(decoded._0)
            }
            Err(e) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestTimestamp",
                        false,
                        duration,
                        Some(&e.to_string()),
                    );
                }

                Err(e.into())
            }
        }
    }

    /// Get the latest round data
    pub async fn latest_round_data(&self) -> Result<(U256, I256, U256, U256, U256)> {
        self.latest_round_data_with_metrics(None, None).await
    }

    /// Get the latest round data with metrics
    pub async fn latest_round_data_with_metrics(
        &self,
        feed_name: Option<&str>,
        network: Option<&str>,
    ) -> Result<(U256, I256, U256, U256, U256)> {
        let start = Instant::now();
        let call = IFluxAggregator::latestRoundDataCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());

        match self.provider.call(&tx).block(BlockId::latest()).await {
            Ok(result) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestRoundData",
                        true,
                        duration,
                        None,
                    );
                }

                let decoded =
                    IFluxAggregator::latestRoundDataCall::abi_decode_returns(&result, true)?;
                Ok((decoded._0, decoded._1, decoded._2, decoded._3, decoded._4))
            }
            Err(e) => {
                let duration = start.elapsed();

                // Record metrics if context is provided
                if let (Some(feed), Some(net)) = (feed_name, network) {
                    ContractMetrics::record_contract_read(
                        feed,
                        net,
                        "latestRoundData",
                        false,
                        duration,
                        Some(&e.to_string()),
                    );
                }

                Err(e.into())
            }
        }
    }

    /// Get the latest on-chain timestamp from latestRoundData
    /// Returns the updatedAt timestamp (index 3 of latestRoundData)
    pub async fn get_latest_on_chain_timestamp(&self) -> Result<u64> {
        self.get_latest_on_chain_timestamp_with_metrics(None, None).await
    }

    /// Get the latest on-chain timestamp with metrics
    pub async fn get_latest_on_chain_timestamp_with_metrics(
        &self,
        feed_name: Option<&str>,
        network: Option<&str>,
    ) -> Result<u64> {
        let (_, _, _, updated_at, _) = self.latest_round_data_with_metrics(feed_name, network).await?;
        Ok(updated_at.to::<u64>())
    }

    /// Get the latest round
    pub async fn latest_round(&self) -> Result<U256> {
        let call = IFluxAggregator::latestRoundCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());
        let result = self.provider.call(&tx).block(BlockId::latest()).await?;

        let decoded = IFluxAggregator::latestRoundCall::abi_decode_returns(&result, true)?;
        Ok(decoded._0)
    }

    /// Get decimals
    pub async fn decimals(&self) -> Result<u8> {
        let call = IFluxAggregator::decimalsCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());
        let result = self.provider.call(&tx).block(BlockId::latest()).await?;

        let decoded = IFluxAggregator::decimalsCall::abi_decode_returns(&result, true)?;
        Ok(decoded._0)
    }

    /// Get min submission value
    pub async fn min_submission_value(&self) -> Result<I256> {
        let call = IFluxAggregator::minSubmissionValueCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());
        let result = self.provider.call(&tx).block(BlockId::latest()).await?;

        let decoded = IFluxAggregator::minSubmissionValueCall::abi_decode_returns(&result, true)?;
        Ok(decoded._0)
    }

    /// Get max submission value
    pub async fn max_submission_value(&self) -> Result<I256> {
        let call = IFluxAggregator::maxSubmissionValueCall {};
        let tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());
        let result = self.provider.call(&tx).block(BlockId::latest()).await?;

        let decoded = IFluxAggregator::maxSubmissionValueCall::abi_decode_returns(&result, true)?;
        Ok(decoded._0)
    }

    /// Submit a new price to the FluxAggregator contract with gas estimation and retry logic
    pub async fn submit_price_with_gas_estimation(
        &self,
        round_id: U256,
        price: I256,
        network_config: &NetworkConfig,
        feed_name: &str,
        tx_log_repo: Option<Arc<TransactionLogRepository>>,
        from_address: Option<Address>,
    ) -> Result<TransactionReceipt> {
        let gas_config = &network_config.gas_config;
        let fee_bumping = &gas_config.fee_bumping;

        // Create the function call
        let call = IFluxAggregator::submitCall {
            _roundId: round_id,
            _submission: price,
        };

        // Build base transaction request
        let mut tx = TransactionRequest::default()
            .to(self.address)
            .input(call.abi_encode().into());

        // Set from address if provided (needed for accurate gas estimation)
        if let Some(from) = from_address {
            tx = tx.from(from);
        }

        // Estimate gas
        let gas_estimator = crate::gas::GasEstimator::<T, P>::new(
            Arc::new(self.provider.clone()),
            network_config.clone(),
        );
        let mut gas_estimate = gas_estimator.estimate_gas(&tx).await?;

        let mut attempt = 0;
        let max_attempts = if fee_bumping.enabled {
            fee_bumping.max_retries + 1
        } else {
            1
        };

        loop {
            attempt += 1;

            // Apply gas settings
            tx = tx.with_gas_limit(gas_estimate.gas_limit.to::<u64>());

            // Apply fee settings based on transaction type
            match network_config.transaction_type.to_lowercase().as_str() {
                "legacy" => {
                    if let Some(gas_price) = gas_estimate.gas_price {
                        tx = tx.with_gas_price(gas_price.to::<u128>());
                    }
                }
                "eip1559" => {
                    if let Some(max_fee) = gas_estimate.max_fee_per_gas {
                        tx = tx.with_max_fee_per_gas(max_fee.to::<u128>());
                    }
                    if let Some(priority_fee) = gas_estimate.max_priority_fee_per_gas {
                        tx = tx.with_max_priority_fee_per_gas(priority_fee.to::<u128>());
                    }
                }
                _ => {
                    warn!("Unknown transaction type, defaulting to EIP-1559");
                    if let Some(max_fee) = gas_estimate.max_fee_per_gas {
                        tx = tx.with_max_fee_per_gas(max_fee.to::<u128>());
                    }
                    if let Some(priority_fee) = gas_estimate.max_priority_fee_per_gas {
                        tx = tx.with_max_priority_fee_per_gas(priority_fee.to::<u128>());
                    }
                }
            }

            info!("Sending transaction (attempt {})", attempt);

            // Record contract write attempt
            let write_start = Instant::now();

            // Send transaction
            let pending_tx = match self.provider.send_transaction(tx.clone()).await {
                Ok(tx) => tx,
                Err(e) => {
                    let write_duration = write_start.elapsed();
                    error!("Failed to send transaction: {}", e);

                    // Record failed contract write
                    ContractMetrics::record_contract_write(
                        feed_name,
                        &network_config.name,
                        false,
                        write_duration,
                        None,
                    );

                    // Check for specific error types
                    let error_str = e.to_string();
                    if error_str.contains("revert") {
                        ContractMetrics::record_transaction_revert(
                            feed_name,
                            &network_config.name,
                            &error_str,
                        );
                    }

                    if attempt >= max_attempts {
                        ContractMetrics::record_transaction_retry(
                            feed_name,
                            &network_config.name,
                            "max_attempts_reached",
                            attempt as u32,
                        );
                        return Err(anyhow::anyhow!(
                            "Failed to send transaction after {} attempts: {}",
                            attempt as u32,
                            e
                        ));
                    }

                    ContractMetrics::record_transaction_retry(
                        feed_name,
                        &network_config.name,
                        "send_error",
                        attempt as u32,
                    );
                    continue;
                }
            };

            let tx_hash = *pending_tx.tx_hash();
            info!("Transaction sent: 0x{:x}", tx_hash);

            // Wait for confirmation with timeout
            let wait_duration = Duration::from_secs(fee_bumping.initial_wait_seconds);

            // Record transaction submission time
            let submission_time = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();

            match tokio::time::timeout(
                wait_duration,
                pending_tx.with_required_confirmations(1).get_receipt(),
            )
            .await
            {
                Ok(Ok(receipt)) => {
                    let write_duration = write_start.elapsed();
                    info!("Transaction confirmed: 0x{:x}", tx_hash);

                    // Record successful contract write
                    ContractMetrics::record_contract_write(
                        feed_name,
                        &network_config.name,
                        true,
                        write_duration,
                        Some(&format!("0x{tx_hash:x}")),
                    );

                    // Record confirmation time
                    let confirmation_time = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap()
                        .as_secs();
                    ContractMetrics::record_confirmation_time(
                        feed_name,
                        &network_config.name,
                        submission_time,
                        confirmation_time,
                    );

                    // Record gas metrics
                    GasMetrics::record_transaction(
                        feed_name,
                        &network_config.name,
                        &receipt,
                        gas_estimate.gas_limit,
                        &network_config.transaction_type,
                    );

                    // Log transaction if repository is available
                    if let Some(repo) = &tx_log_repo {
                        if let Err(e) = Self::log_transaction(
                            repo,
                            &tx_hash,
                            &receipt,
                            feed_name,
                            &network_config.name,
                            &gas_estimate,
                            &network_config.transaction_type,
                        )
                        .await
                        {
                            error!("Failed to log transaction: {}", e);
                        }
                    }

                    return Ok(receipt);
                }
                Ok(Err(e)) => {
                    error!("Transaction failed: {}", e);

                    // Record failed transaction
                    GasMetrics::record_failed_transaction(
                        feed_name,
                        &network_config.name,
                        gas_estimate.gas_limit,
                        gas_estimate.gas_price.or(gas_estimate.max_fee_per_gas),
                        &network_config.transaction_type,
                        &e.to_string(),
                    );

                    if attempt >= max_attempts {
                        return Err(anyhow::anyhow!(
                            "Transaction failed after {} attempts: {}",
                            attempt as u32,
                            e
                        ));
                    }
                }
                Err(_) => {
                    warn!(
                        "Transaction timed out after {} seconds: 0x{:x}",
                        wait_duration.as_secs(),
                        tx_hash
                    );
                    if attempt >= max_attempts {
                        return Err(anyhow::anyhow!(
                            "Transaction timed out after {} attempts",
                            attempt
                        ));
                    }
                }
            }

            // Bump fees for retry
            if fee_bumping.enabled && attempt < max_attempts {
                gas_estimate = gas_estimator.bump_fees(&gas_estimate, attempt);
                info!("Bumping fees for retry attempt {}", attempt + 1);
            }
        }
    }

    /// Log transaction details to the database
    async fn log_transaction(
        repo: &Arc<TransactionLogRepository>,
        tx_hash: &alloy::primitives::TxHash,
        receipt: &TransactionReceipt,
        feed_name: &str,
        network_name: &str,
        gas_estimate: &GasEstimate,
        tx_type: &str,
    ) -> Result<()> {
        let gas_used = receipt.gas_used;
        let gas_limit = gas_estimate.gas_limit;
        let efficiency_percent = (gas_used as f64 / gas_limit.to::<u128>() as f64) * 100.0;

        let gas_price_gwei = if let Some(price) = gas_estimate.gas_price {
            alloy::primitives::utils::format_units(price, "gwei")?.parse::<f64>()?
        } else if let Some(max_fee) = gas_estimate.max_fee_per_gas {
            alloy::primitives::utils::format_units(max_fee, "gwei")?.parse::<f64>()?
        } else {
            0.0
        };

        let total_cost_wei = U256::from(gas_used) * gas_estimate.gas_price.unwrap_or(U256::ZERO);

        let details = TransactionDetails {
            tx_hash: format!("0x{tx_hash:x}"),
            feed_name: feed_name.to_string(),
            network: network_name.to_string(),
            gas_limit: gas_limit.to::<u64>(),
            gas_used: gas_used as u64,
            gas_price_gwei,
            total_cost_wei: total_cost_wei.to::<u128>(),
            efficiency_percent,
            tx_type: tx_type.to_string(),
            status: if receipt.status() {
                "success"
            } else {
                "failed"
            }
            .to_string(),
            block_number: receipt.block_number.unwrap_or(0),
            error_message: None,
        };

        repo.save_transaction(details).await?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_transaction_details_creation() {
        let details = TransactionDetails {
            tx_hash: "0xabc123".to_string(),
            feed_name: "eth_usd".to_string(),
            network: "ethereum".to_string(),
            gas_limit: 200000,
            gas_used: 150000,
            gas_price_gwei: 35.5,
            total_cost_wei: 5325000000000000u128,
            efficiency_percent: 75.0,
            tx_type: "eip1559".to_string(),
            status: "success".to_string(),
            block_number: 15000000,
            error_message: None,
        };

        assert_eq!(details.feed_name, "eth_usd");
        assert_eq!(details.efficiency_percent, 75.0);
        assert_eq!(details.status, "success");
    }

    #[test]
    fn test_gas_estimate_conversion() {
        let estimate = GasEstimate {
            gas_limit: U256::from(250000),
            gas_price: Some(U256::from(32000000000u64)), // 32 gwei
            max_fee_per_gas: None,
            max_priority_fee_per_gas: None,
        };

        assert_eq!(estimate.gas_limit, U256::from(250000));
        assert!(estimate.gas_price.is_some());
        assert!(estimate.max_fee_per_gas.is_none());
        assert!(estimate.max_priority_fee_per_gas.is_none());
    }

    #[test]
    fn test_address_creation() {
        let addr_str = "0x1234567890123456789012345678901234567890";
        let addr = addr_str.parse::<Address>().unwrap();
        assert_eq!(format!("0x{addr:x}"), addr_str.to_lowercase());
    }

    #[test]
    fn test_i256_edge_cases() {
        // Test maximum positive value
        let max_positive = I256::MAX;
        assert!(max_positive > I256::ZERO);

        // Test minimum negative value
        let min_negative = I256::MIN;
        assert!(min_negative < I256::ZERO);

        // Test zero
        let zero = I256::ZERO;
        assert_eq!(zero, I256::try_from(0).unwrap());
    }

    #[test]
    fn test_contract_call_encoding() {
        // Test latestAnswer call encoding
        let call = IFluxAggregator::latestAnswerCall {};
        let encoded = call.abi_encode();
        assert_eq!(encoded.len(), 4); // Function selector only

        // Test submit call encoding
        let submit_call = IFluxAggregator::submitCall {
            _roundId: U256::from(1),
            _submission: I256::try_from(100).unwrap(),
        };
        let submit_encoded = submit_call.abi_encode();
        assert!(submit_encoded.len() > 4); // Function selector + parameters
    }

    #[test]
    fn test_transaction_type_strings() {
        let eip1559 = "eip1559";
        let legacy = "legacy";
        let eip2930 = "eip2930";

        assert_eq!(eip1559, "eip1559");
        assert_eq!(legacy, "legacy");
        assert_eq!(eip2930, "eip2930");
    }

    #[test]
    fn test_error_message_parsing() {
        let revert_error = "execution reverted: price must be positive";
        assert!(revert_error.contains("revert"));

        let gas_error = "out of gas";
        assert!(gas_error.contains("gas"));

        let nonce_error = "nonce too low";
        assert!(nonce_error.contains("nonce"));
    }

    #[test]
    fn test_submission_timestamp() {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        assert!(now > 0);
        assert!(now < u64::MAX);
    }

    #[test]
    fn test_gas_calculations() {
        // Test gas cost calculation
        let gas_used = 150000u64;
        let gas_price_wei = 35_000_000_000u64; // 35 gwei
        let total_cost_wei = gas_used * gas_price_wei;

        assert_eq!(total_cost_wei, 5_250_000_000_000_000);

        // Test efficiency calculation
        let gas_limit = 200000u64;
        let efficiency = (gas_used as f64 / gas_limit as f64) * 100.0;
        assert_eq!(efficiency, 75.0);
    }

    #[test]
    fn test_retry_logic_values() {
        let _max_attempts = 3;
        let initial_wait_seconds = 30;
        let multiplier = 1.5;

        // Calculate wait times for each retry
        let wait_1 = initial_wait_seconds as f64;
        let wait_2 = wait_1 * multiplier;
        let wait_3 = wait_2 * multiplier;

        assert_eq!(wait_1, 30.0);
        assert_eq!(wait_2, 45.0);
        assert_eq!(wait_3, 67.5);
    }

    #[test]
    fn test_efficiency_calculation() {
        // Test normal case
        let gas_used = 150000u128;
        let gas_limit = 200000u128;
        let efficiency = (gas_used as f64 / gas_limit as f64) * 100.0;
        assert_eq!(efficiency, 75.0);

        // Test full usage
        let full_efficiency = (200000f64 / 200000f64) * 100.0;
        assert_eq!(full_efficiency, 100.0);

        // Test low efficiency
        let low_efficiency = (50000f64 / 200000f64) * 100.0;
        assert_eq!(low_efficiency, 25.0);
    }
}

//! Builder patterns for complex configuration objects
//!
//! This module provides builder patterns for creating complex configuration objects
//! with sensible defaults and validation. These builders make it easier to create
//! configurations programmatically and reduce boilerplate code.

use super::metrics_config::MetricsConfig;
use super::models::*;
use crate::gas_price::models::GasPriceFeedConfig;
use crate::scheduled_tasks::models::ScheduledTask;
use alloy::primitives::I256;
use serde_json::Value;

/// Builder for creating OmikujiConfig objects with a fluent API
#[derive(Debug, Clone)]
pub struct OmikujiConfigBuilder {
    networks: Vec<Network>,
    datafeeds: Vec<Datafeed>,
    database_cleanup: DatabaseCleanupConfig,
    key_storage: KeyStorageConfig,
    metrics: MetricsConfig,
    gas_price_feeds: GasPriceFeedConfig,
    scheduled_tasks: Vec<ScheduledTask>,
}

impl OmikujiConfigBuilder {
    /// Create a new OmikujiConfigBuilder with default values
    pub fn new() -> Self {
        Self {
            networks: Vec::new(),
            datafeeds: Vec::new(),
            database_cleanup: DatabaseCleanupConfig::default(),
            key_storage: KeyStorageConfig::default(),
            metrics: MetricsConfig::default(),
            gas_price_feeds: GasPriceFeedConfig::default(),
            scheduled_tasks: Vec::new(),
        }
    }

    /// Add a network to the configuration
    pub fn add_network(mut self, network: Network) -> Self {
        self.networks.push(network);
        self
    }

    /// Add multiple networks to the configuration
    pub fn add_networks(mut self, networks: Vec<Network>) -> Self {
        self.networks.extend(networks);
        self
    }

    /// Add a datafeed to the configuration
    pub fn add_datafeed(mut self, datafeed: Datafeed) -> Self {
        self.datafeeds.push(datafeed);
        self
    }

    /// Add multiple datafeeds to the configuration
    pub fn add_datafeeds(mut self, datafeeds: Vec<Datafeed>) -> Self {
        self.datafeeds.extend(datafeeds);
        self
    }

    /// Set the database cleanup configuration
    pub fn with_database_cleanup(mut self, config: DatabaseCleanupConfig) -> Self {
        self.database_cleanup = config;
        self
    }

    /// Set the key storage configuration
    pub fn with_key_storage(mut self, config: KeyStorageConfig) -> Self {
        self.key_storage = config;
        self
    }

    /// Set the metrics configuration
    pub fn with_metrics(mut self, config: MetricsConfig) -> Self {
        self.metrics = config;
        self
    }

    /// Set the gas price feeds configuration
    pub fn with_gas_price_feeds(mut self, config: GasPriceFeedConfig) -> Self {
        self.gas_price_feeds = config;
        self
    }

    /// Add a scheduled task to the configuration
    pub fn add_scheduled_task(mut self, task: ScheduledTask) -> Self {
        self.scheduled_tasks.push(task);
        self
    }

    /// Add multiple scheduled tasks to the configuration
    pub fn add_scheduled_tasks(mut self, tasks: Vec<ScheduledTask>) -> Self {
        self.scheduled_tasks.extend(tasks);
        self
    }

    /// Build the OmikujiConfig
    pub fn build(self) -> OmikujiConfig {
        OmikujiConfig {
            networks: self.networks,
            datafeeds: self.datafeeds,
            database_cleanup: self.database_cleanup,
            key_storage: self.key_storage,
            metrics: self.metrics,
            gas_price_feeds: self.gas_price_feeds,
            scheduled_tasks: self.scheduled_tasks,
            event_monitors: Vec::new(),
            default_execution_limits: Default::default(),
        }
    }
}

impl Default for OmikujiConfigBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Builder for creating Network configurations with a fluent API
#[derive(Debug, Clone)]
pub struct NetworkBuilder {
    name: String,
    rpc_url: String,
    ws_url: Option<String>,
    transaction_type: String,
    gas_config: GasConfig,
    gas_token: String,
    gas_token_symbol: String,
}

impl NetworkBuilder {
    /// Create a new NetworkBuilder with default values
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            rpc_url: "http://localhost:8545".to_string(),
            ws_url: None,
            transaction_type: "eip1559".to_string(),
            gas_config: GasConfig::default(),
            gas_token: "ethereum".to_string(),
            gas_token_symbol: "ETH".to_string(),
        }
    }

    /// Set the RPC URL for this network
    pub fn with_rpc_url(mut self, url: impl Into<String>) -> Self {
        self.rpc_url = url.into();
        self
    }

    /// Set the WebSocket URL for this network
    pub fn with_ws_url(mut self, url: impl Into<String>) -> Self {
        self.ws_url = Some(url.into());
        self
    }

    /// Set the transaction type (legacy, eip1559)
    pub fn with_transaction_type(mut self, tx_type: impl Into<String>) -> Self {
        self.transaction_type = tx_type.into();
        self
    }

    /// Set the gas configuration
    pub fn with_gas_config(mut self, config: GasConfig) -> Self {
        self.gas_config = config;
        self
    }

    /// Set the gas token details
    pub fn with_gas_token(mut self, token: impl Into<String>, symbol: impl Into<String>) -> Self {
        self.gas_token = token.into();
        self.gas_token_symbol = symbol.into();
        self
    }

    /// Build the Network configuration
    pub fn build(self) -> Network {
        Network {
            name: self.name,
            nodes: vec![crate::config::models::NetworkNode {
                name: "Default Node".to_string(),
                rpc_url: self.rpc_url,
                ws_url: None,
            }],
            transaction_type: self.transaction_type,
            gas_config: self.gas_config,
            gas_token: self.gas_token,
            gas_token_symbol: self.gas_token_symbol,
            balance_alerts: None,
            rpc_url: None,
            ws_url: None,
        }
    }

    /// Create a common Ethereum mainnet configuration
    pub fn ethereum_mainnet(rpc_url: impl Into<String>) -> Network {
        Self::new("ethereum-mainnet")
            .with_rpc_url(rpc_url)
            .with_gas_token("ethereum", "ETH")
            .build()
    }

    /// Create a common BASE mainnet configuration
    pub fn base_mainnet(rpc_url: impl Into<String>) -> Network {
        Self::new("base-mainnet")
            .with_rpc_url(rpc_url)
            .with_gas_token("ethereum", "ETH")
            .build()
    }

    /// Create a common Polygon mainnet configuration
    pub fn polygon_mainnet(rpc_url: impl Into<String>) -> Network {
        Self::new("polygon-mainnet")
            .with_rpc_url(rpc_url)
            .with_gas_token("polygon", "MATIC")
            .build()
    }

    /// Create a common development/localhost configuration
    pub fn localhost(port: u16) -> Network {
        Self::new("localhost")
            .with_rpc_url(format!("http://localhost:{port}"))
            .with_transaction_type("legacy")
            .build()
    }
}

/// Builder for creating Datafeed configurations with a fluent API
#[derive(Debug, Clone)]
pub struct DatafeedBuilder {
    name: String,
    networks: String,
    check_frequency: u64,
    contract_address: String,
    contract_type: String,
    read_contract_config: bool,
    minimum_update_frequency: u64,
    deviation_threshold_pct: f64,
    feed_url: String,
    feed_json_path: String,
    feed_json_path_timestamp: Option<String>,
    decimals: Option<u8>,
    min_value: Option<I256>,
    max_value: Option<I256>,
    data_retention_days: u32,
}

impl DatafeedBuilder {
    /// Create a new DatafeedBuilder with default values
    pub fn new(name: impl Into<String>, network: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            networks: network.into(),
            check_frequency: 60, // 1 minute
            contract_address: "0x0000000000000000000000000000000000000000".to_string(),
            contract_type: "fluxmon".to_string(),
            read_contract_config: true,
            minimum_update_frequency: 300, // 5 minutes
            deviation_threshold_pct: 0.5,  // 0.5%
            feed_url: "https://api.example.com/price".to_string(),
            feed_json_path: "$.price".to_string(),
            feed_json_path_timestamp: None,
            decimals: None,
            min_value: None,
            max_value: None,
            data_retention_days: 7,
        }
    }

    /// Set the check frequency in seconds
    pub fn with_check_frequency(mut self, seconds: u64) -> Self {
        self.check_frequency = seconds;
        self
    }

    /// Set the contract address
    pub fn with_contract_address(mut self, address: impl Into<String>) -> Self {
        self.contract_address = address.into();
        self
    }

    /// Set the contract type
    pub fn with_contract_type(mut self, contract_type: impl Into<String>) -> Self {
        self.contract_type = contract_type.into();
        self
    }

    /// Set whether to read configuration from the contract
    pub fn with_read_contract_config(mut self, read_config: bool) -> Self {
        self.read_contract_config = read_config;
        self
    }

    /// Set the minimum update frequency in seconds
    pub fn with_minimum_update_frequency(mut self, seconds: u64) -> Self {
        self.minimum_update_frequency = seconds;
        self
    }

    /// Set the deviation threshold percentage
    pub fn with_deviation_threshold(mut self, percent: f64) -> Self {
        self.deviation_threshold_pct = percent;
        self
    }

    /// Set the feed URL
    pub fn with_feed_url(mut self, url: impl Into<String>) -> Self {
        self.feed_url = url.into();
        self
    }

    /// Set the JSON path for extracting the price
    pub fn with_feed_json_path(mut self, path: impl Into<String>) -> Self {
        self.feed_json_path = path.into();
        self
    }

    /// Set the JSON path for extracting the timestamp
    pub fn with_feed_json_path_timestamp(mut self, path: Option<String>) -> Self {
        self.feed_json_path_timestamp = path;
        self
    }

    /// Set the number of decimals
    pub fn with_decimals(mut self, decimals: u8) -> Self {
        self.decimals = Some(decimals);
        self
    }

    /// Set the minimum valid value
    pub fn with_min_value(mut self, min: I256) -> Self {
        self.min_value = Some(min);
        self
    }

    /// Set the maximum valid value
    pub fn with_max_value(mut self, max: I256) -> Self {
        self.max_value = Some(max);
        self
    }

    /// Set the data retention period in days
    pub fn with_data_retention_days(mut self, days: u32) -> Self {
        self.data_retention_days = days;
        self
    }

    /// Build the Datafeed configuration
    pub fn build(self) -> Datafeed {
        Datafeed {
            name: self.name,
            networks: self.networks,
            check_frequency: self.check_frequency,
            contract_address: self.contract_address,
            contract_type: self.contract_type,
            read_contract_config: self.read_contract_config,
            minimum_update_frequency: self.minimum_update_frequency,
            deviation_threshold_pct: self.deviation_threshold_pct,
            feed_url: self.feed_url,
            feed_json_path: self.feed_json_path,
            feed_json_path_timestamp: self.feed_json_path_timestamp,
            decimals: self.decimals,
            min_value: self.min_value,
            max_value: self.max_value,
            data_retention_days: self.data_retention_days,
        }
    }

    /// Create a common ETH/USD price feed configuration
    pub fn eth_usd_feed(
        network: impl Into<String>,
        contract_address: impl Into<String>,
    ) -> Datafeed {
        Self::new("eth_usd", network)
            .with_contract_address(contract_address)
            .with_feed_url(
                "https://api.coingecko.com/api/v3/simple/price?ids=ethereum&vs_currencies=usd",
            )
            .with_feed_json_path("$.ethereum.usd")
