        let max_positive = I256::MAX;
        assert!(max_positive > I256::ZERO);

        // Test minimum negative value
        let min_negative = I256::MIN;
        assert!(min_negative < I256::ZERO);

        // Test zero
        let zero = I256::ZERO;
        assert_eq!(zero, I256::try_from(0).unwrap());
    }

